float number(jass::Real value){return std::bit_cast<float>(value.bits());}
void commandStack(const wchar_t* root,const wchar_t* map){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(4);if(!session.ais()[0])throw std::runtime_error("Campaign AI missing");auto& avm=*session.ais()[0]->runtime;auto& vm=session.runtime();auto player=vm.handle("player",0x100000);auto get=[&](const char* name){return std::bit_cast<int>(avm.invoke(name).bits);};auto push=[&](int command,int value){vm.invoke("CommandAI",std::array{player,vm.integer(command),vm.integer(value)});};
    if(get("CommandsWaiting")!=0 || get("GetLastCommand")!=-1 || get("GetLastData")!=-1)throw std::runtime_error("Empty AI stack state differs");avm.invoke("PopLastCommand");for(int i=0;i<13;++i)push(100+i,-200-i);if(get("CommandsWaiting")!=12)throw std::runtime_error("AI stack capacity differs");for(int i=11;i>=0;--i){if(get("GetLastCommand")!=100+i || get("GetLastData")!=-200-i)throw std::runtime_error("AI command stack order or data differs");avm.invoke("PopLastCommand");}if(get("CommandsWaiting")!=0 || get("GetLastCommand")!=-1 || get("GetLastData")!=-1)throw std::runtime_error("AI stack did not clear");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS AI command stack order, capacity and empty behavior\n";
}
void human06Captain(const wchar_t* root,bool approach=false){
    Archives archives(root);auto map=archives.readCandidates({"Maps\\Campaign\\Human06.w3m"},ArchiveScope::Common);if(!map)throw std::runtime_error("Original Human06 map missing");archives.mountMap(std::make_shared<const Bytes>(map->bytes),"Human06.w3m");auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));session.campaignContext(true,1);session.attachWorld(std::move(world));session.audioSimulationClock();session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();std::uint32_t house=0;bool advanced=false,engaged=false;
    while(session.simulationTime()<(approach?600:370) && session.exitRequest()==SessionExit::None){session.advance(.25);auto candidate=vm.global("udg_MalganisTargetHouse").bits;if(!house && candidate && session.units().contains(candidate) && session.ais()[6] && session.ais()[6]->pointAttack && (!approach || (number(session.units().at(candidate)->x)==5920 && number(session.units().at(candidate)->y)==32)))house=candidate;auto hero=vm.global("udg_MalganisVariable").bits;if(house && session.units().contains(hero) && session.units().at(hero)->combat.target==house)engaged=true;if(house && session.units().contains(house) && number(session.units().at(house)->life)<=0){advanced=true;break;}}
    if(!house || !engaged || !advanced)throw std::runtime_error("Original Human06 captain did not attack and destroy its first assigned building");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS Human06 "<<(approach?"obstructed target approach":"teleport and first target building")<<" time="<<session.simulationTime()<<"\n";
}
void human06Conversion(const wchar_t* root){
    Archives archives(root);auto map=archives.readCandidates({"Maps\\Campaign\\Human06.w3m"},ArchiveScope::Common);if(!map)throw std::runtime_error("Original Human06 map missing");archives.mountMap(std::make_shared<const Bytes>(map->bytes),"Human06.w3m");auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));session.campaignContext(true,1);session.attachWorld(std::move(world));session.audioSimulationClock();session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();std::set<std::uint32_t> casters;bool converted=false;
    while(session.simulationTime()<360 && session.exitRequest()==SessionExit::None){session.advance(.25);for(auto& [id,u]:session.units())if(u->type==ObjectData::code("UC05") && u->owner==7)casters.insert(id);for(auto& [id,u]:session.units())if(u->type==ObjectData::code("nzom") && u->owner==2 && casters.contains(u->summoner) && !session.units().contains(u->summoner)){converted=true;break;}if(converted)break;}
    if(!converted)throw std::runtime_error("Original Human06 conversion did not remove its temporary caster and transfer the zombie");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS Human06 conversion summon event time="<<session.simulationTime()<<"\n";
}
void zeppelinReachability(const wchar_t* root,const wchar_t* map,int journey=0){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(4);auto& vm=session.runtime();auto& ai=*session.ais()[0];auto& avm=*ai.runtime;std::vector<std::uint32_t> existingShops;for(auto& [id,u]:session.units()){if(u->owner==0)u->paused=true;if(ObjectData::name(u->type)=="ngad")existingShops.push_back(id);}for(auto id:existingShops)vm.invoke("RemoveUnit",std::array{vm.handle("unit",id)});auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto spawn=[&](unsigned owner,const char* type,int x,int y){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),vm.integer(int(ObjectData::code(type))),real(x),real(y),real(0)});};auto buyer=spawn(0,"hpea",8765,1932),island=spawn(15,"ngad",3599,2077),land=spawn(15,"ngad",-7904,2080);auto unit=session.units().at(buyer.bits),remote=session.units().at(island.bits),seller=session.units().at(land.bits);auto& path=*session.world();auto movement=pathMovement(unit->movementType);if(path.pathRegionsNear({unit->x,unit->y},{remote->x,remote->y},unit->collision,movement,512)!=false || path.pathRegionsNear({unit->x,unit->y},{seller->x,seller->y},unit->collision,movement,512)!=true)throw std::runtime_error("Laboratory reachability fixture differs");for(auto shop:{island,land})vm.invoke("AddUnitToStock",std::array{shop,vm.integer(int(ObjectData::code("nzep"))),vm.integer(1),vm.integer(1)});for(int field:{1,2,4,6})vm.invoke("SetPlayerState",std::array{vm.handle("player",0x100000),vm.handle("playerstate",field),vm.integer(field<4?10000:200)});vm.invoke("ShowUnit",std::array{land,vm.boolean(false)});auto revision=unit->combat.revision;avm.invoke("PurchaseZeppelin");if(ai.zeppelinPurchase || unit->combat.revision!=revision || unit->currentOrder)throw std::runtime_error("Unreachable laboratory changed the buyer's orders");vm.invoke("ShowUnit",std::array{land,vm.boolean(true)});avm.invoke("GetZeppelin");avm.invoke("SingleMeleeAttack",std::array{avm.boolean(false),avm.boolean(false),avm.boolean(false),avm.boolean(false)});if(!ai.zeppelinPurchase || ai.zeppelinPurchase->buyer!=buyer.bits || ai.zeppelinPurchase->shop!=land.bits)throw std::runtime_error("AI selected an unreachable laboratory instead of the reachable one");if(journey){unit->pathing=false;vm.invoke("SetUnitInvulnerable",std::array{buyer,vm.boolean(true)});if(journey==2){unit->moveSpeed={};auto deadline=ai.zeppelinPurchase->deadline;if(deadline<=session.simulationTime() || deadline>session.simulationTime()+600)throw std::runtime_error("Invalid purchase deadline");while(ai.zeppelinPurchase && session.simulationTime()<deadline+2)session.advance(1);if(ai.zeppelinPurchase)throw std::runtime_error("Motionless buyer kept the reservation beyond its deadline");std::cout<<"PASS stalled_zeppelin_trip_released\n";}else{auto start=session.simulationTime();bool bought=false;for(unsigned n=0;n<240 && !bought;++n){session.advance(1);for(auto& [id,u]:session.units())if(u->owner==0 && ObjectData::name(u->type)=="nzep" && number(u->life)>0)bought=true;if(!bought && session.simulationTime()-start>61 && !ai.zeppelinPurchase)throw std::runtime_error("Long reachable trip lost its buyer reservation");}if(!bought || session.simulationTime()-start<=60)throw std::runtime_error("Long reachable trip did not purchase after 60 seconds");std::cout<<"PASS long_zeppelin_trip elapsed="<<session.simulationTime()-start<<"\n";}}else{vm.invoke("RemoveUnit",std::array{land});session.advance(1.1);if(ai.zeppelinPurchase)throw std::runtime_error("Removed laboratory retained the buyer reservation");}if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS reachable_zeppelin_laboratory\n";
}
void zeppelinPurchase(const wchar_t* root,const wchar_t* map){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(4);auto& vm=session.runtime();auto& ai=*session.ais()[0];auto& avm=*ai.runtime;auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto spawn=[&](unsigned owner,const char* type,int x,int y){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000+owner),vm.integer(int(ObjectData::code(type))),real(x),real(y),real(0)});};auto buyer=spawn(0,"hpea",8200,1500),shop=spawn(15,"ngad",9000,1500);vm.invoke("SetUnitInvulnerable",std::array{buyer,vm.boolean(true)});vm.invoke("AddUnitToStock",std::array{shop,vm.integer(int(ObjectData::code("nzep"))),vm.integer(1),vm.integer(1)});for(int field:{1,2,4,6})vm.invoke("SetPlayerState",std::array{vm.handle("player",0x100000),vm.handle("playerstate",field),vm.integer(field<4?10000:200)});avm.invoke("GetZeppelin");avm.invoke("SingleMeleeAttack",std::array{avm.boolean(false),avm.boolean(false),avm.boolean(false),avm.boolean(false)});if(!ai.zeppelinPurchase || ai.zeppelinPurchase->buyer!=buyer.bits || ai.zeppelinPurchase->shop!=shop.bits)throw std::runtime_error("AI did not send the buyer to the laboratory");for(int n=0;n<320;++n){session.advance(.25);for(auto& [id,u]:session.units())if(u->owner==0 && ObjectData::name(u->type)=="nzep" && number(u->life)>0){auto& stock=session.units().at(shop.bits)->stock;auto entry=std::find_if(stock.begin(),stock.end(),[](const auto& item){return !item.item && item.type==ObjectData::code("nzep");});if(ai.zeppelinPurchase || entry==stock.end() || entry->current!=0 || session.config().players[0].states.at(1)>=10000 || GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Zeppelin purchase did not consume stock and gold or release reservation");std::cout<<"PASS ai_zeppelin_purchase time="<<session.simulationTime()<<"\n";return;}}throw std::runtime_error("AI did not buy the Zeppelin");
}
