    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(4);auto& vm=session.runtime();auto& ai=*session.ais()[0];auto& avm=*ai.runtime;auto real=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto spawn=[&](const char* type,int x,int y){return vm.invoke("CreateUnit",std::array{vm.handle("player",0x100000),vm.integer(int(ObjectData::code(type))),real(x),real(y),real(0)});};auto soldier=spawn("hfoo",9000,1500),carrier=spawn("nzep",8500,1500);auto fast=slow?spawn("hfoo",8500,1500):vm.handle("unit",0);auto unit=session.units().at(soldier.bits),ship=session.units().at(carrier.bits);if(slow)unit->moveSpeed=jass::Real::fromInteger(5);WorldPoint island{jass::Real::fromInteger(3599),jass::Real::fromInteger(2077)};if(session.world()->pathRegionsNear({unit->x,unit->y},island,unit->collision,pathMovement(unit->movementType),512)!=false)throw std::runtime_error("Island fixture unexpectedly reachable on foot");vm.invoke("SetUnitInvulnerable",std::array{soldier,vm.boolean(true)});if(slow)vm.invoke("SetUnitInvulnerable",std::array{fast,vm.boolean(true)});ai.assault.clear();ai.assault[unit->type]=slow?2:1;ai.captain.clear();ai.captain.insert(soldier.bits);if(slow)ai.captain.insert(fast.bits);avm.invoke("LoadZepWave",std::array{avm.integer(3599),avm.integer(2077)});if(!ai.zeppelinWave || !ai.zeppelinWave->passengers.contains(soldier.bits) || unit->combat.board!=carrier.bits || unit->route.empty())throw std::runtime_error("AI did not assign the soldier to approach transport");auto enemy=vm.handle("unit",0);if(targeted){enemy=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100001),vm.integer(int(ObjectData::code("hpea"))),real(3599),real(2077),real(0)});vm.invoke("SetUnitInvulnerable",std::array{enemy,vm.boolean(true)});session.units().at(enemy.bits)->paused=true;for(int i=0;i<2;++i){avm.invoke("AttackMoveKill",std::array{avm.handle("unit",enemy.bits)});if(!ai.zeppelinWave || !ai.zeppelinWave->passengers.contains(soldier.bits))throw std::runtime_error("Unit attack cancelled transport to the same destination");}if(targetSmallMove){auto ticket=ai.zeppelinWave->ticket;vm.invoke("SetUnitPosition",std::array{enemy,real(3631),real(2077)});session.advance(1);if(!ai.zeppelinWave || ai.zeppelinWave->ticket!=ticket)throw std::runtime_error("Small target movement cancelled the transport");avm.invoke("AttackMoveKill",std::array{avm.handle("unit",enemy.bits)});if(!ai.zeppelinWave || ai.zeppelinWave->ticket!=ticket)throw std::runtime_error("Repeated moving-target order cancelled the transport");}if(targetChanged){auto ticket=ai.zeppelinWave->ticket;vm.invoke("SetUnitPosition",std::array{enemy,real(4200),real(2077)});avm.invoke("AttackMoveKill",std::array{avm.handle("unit",enemy.bits)});if(ai.zeppelinWave && (ai.zeppelinWave->ticket==ticket || number(ai.zeppelinWave->destination.x)!=4200 || number(ai.zeppelinWave->destination.y)!=2077))throw std::runtime_error("Changed attack destination retained the old transport wave");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS ai_changed_unit_target_cancels_wave\n";return;}}else avm.invoke("AttackMoveXY",std::array{avm.integer(3599),avm.integer(2077)});bool boarded=false;double boardedAt=0;for(int n=0;n<(slow?1600:720);++n){session.advance(.25);if(!boarded && unit->transport==carrier.bits && !ship->cargo.empty()){boarded=true;boardedAt=session.simulationTime();if(targetSmallMove){auto ticket=ai.zeppelinWave->ticket;vm.invoke("SetUnitPosition",std::array{enemy,real(3663),real(2077)});avm.invoke("AttackMoveKill",std::array{avm.handle("unit",enemy.bits)});if(!ai.zeppelinWave || ai.zeppelinWave->ticket!=ticket)throw std::runtime_error("Moving target interrupted boarded passengers");}}if(slow && n==184 && (!ai.zeppelinWave || ai.zeppelinWave->departing || session.units().at(fast.bits)->transport!=carrier.bits))throw std::runtime_error("Carrier abandoned a slow passenger after boarding a faster one");if(boarded && !ai.zeppelinWave && !unit->transport && std::hypot(number(unit->x)-3599,number(unit->y)-2077)<600){if(slow && (boardedAt<49 || session.units().at(fast.bits)->transport || std::hypot(number(session.units().at(fast.bits)->x)-3599,number(session.units().at(fast.bits)->y)-2077)>=600))throw std::runtime_error("Mixed transport did not retain both passengers through the long boarding interval");if(targeted){if(targetSmallMove)vm.invoke("SetUnitInvulnerable",std::array{enemy,vm.boolean(false)});avm.invoke("AttackMoveKill",std::array{avm.handle("unit",enemy.bits)});if(unit->combat.target!=enemy.bits && !unit->combat.attackMove)throw std::runtime_error("Landed soldier did not resume the unit attack");}if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS ai_island_transport_wave time="<<session.simulationTime()<<"\n";return;}}throw std::runtime_error("AI transport wave did not land on the island");
