void meleeBuildRoute(const wchar_t* root,const wchar_t* map){
    auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());if(!setup.control(1,SlotControl::ComputerNormal) || !setup.race(1,3))throw std::runtime_error("Cannot configure undead AI");session.applySetup(setup);session.startMain();std::shared_ptr<UnitState> builder;for(int n=0;n<960 && !builder;++n){session.advance(1./32);for(auto& [id,u]:session.units())if(u->owner==1 && u->buildOrder && ObjectData::name(u->buildOrder->type)=="uaod" && !u->route.empty()){builder=u;break;}}if(!builder)throw std::runtime_error("AI did not issue altar construction route");auto end=builder->route.back();auto savedSpeed=builder->moveSpeed;bool savedPathing=builder->pathing;builder->pathing=false;builder->moveSpeed=real(1);WorldPoint detour{builder->x,real(number(builder->y)+64)};builder->route.insert(builder->route.begin()+builder->waypoint,detour);auto index=builder->waypoint;session.advance(.5);if(!builder->buildOrder || builder->waypoint!=index || builder->route.size()<=index || builder->route[index].x.bits()!=detour.x.bits() || builder->route[index].y.bits()!=detour.y.bits() || builder->route.back().x.bits()!=end.x.bits() || builder->route.back().y.bits()!=end.y.bits())throw std::runtime_error("Construction discarded a valid avoidance route");WorldPoint invalid{real(number(builder->x)+1000),real(number(builder->y)+1000)};builder->route.back()=invalid;session.advance(.5);if(builder->route.empty() || (builder->route.back().x.bits()==invalid.x.bits() && builder->route.back().y.bits()==invalid.y.bits()))throw std::runtime_error("Construction retained a route to an invalid site");builder->pathing=savedPathing;builder->moveSpeed=savedSpeed;for(unsigned n=0;n<160;++n){session.advance(1);for(auto& [id,u]:session.units())if(u->owner==1 && ObjectData::name(u->type)=="uaod" && !u->construction && number(u->life)>0){if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS construction_route_and_altar_completion time="<<session.simulationTime()<<"\n";return;}}throw std::runtime_error("AI did not finish altar construction");
}
void meleeMine(const wchar_t* root,const wchar_t* map,unsigned race,const char* coverType){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());if(!setup.control(1,SlotControl::ComputerNormal) || !setup.race(1,race))throw std::runtime_error("Cannot configure melee AI race");session.applySetup(setup);session.startMain();session.advance(10);if(!session.ais()[1])throw std::runtime_error("Melee AI did not start");auto& vm=*session.ais()[1]->runtime;std::uint32_t cover=0;for(auto& [id,u]:session.units())if(u->owner==1 && ObjectData::name(u->type)==coverType && u->mineSource){cover=id;break;}if(!cover)throw std::runtime_error("Covered starting mine not found");auto mine=session.units().at(cover);auto base=session.units().at(mine->mineSource);int initial=base->resources;if(initial<=0 || mine->resources!=0 || std::bit_cast<int>(vm.invoke("GetMinesOwned").bits)!=1 || std::bit_cast<int>(vm.invoke("GetGoldOwned").bits)!=initial)throw std::runtime_error("AI mine queries did not use covered mine balance");session.advance(50);auto states=session.config().players[1].states;if(base->resources>=initial || states[15]<=0)throw std::runtime_error("Melee AI did not mine covered gold");if(std::bit_cast<int>(vm.invoke("GetGoldOwned").bits)!=base->resources)throw std::runtime_error("AI gold query did not follow mine depletion");int extracted=initial-base->resources;auto& mapvm=session.runtime();auto coverHandle=mapvm.handle("unit",cover);mapvm.invoke("SetResourceAmount",std::array{coverHandle,mapvm.integer(0)});if(vm.invoke("GetMinesOwned").bits || vm.invoke("GetGoldOwned").bits)throw std::runtime_error("Depleted covered mine remained available");mapvm.invoke("SetResourceAmount",std::array{coverHandle,mapvm.integer(73)});if(vm.invoke("GetMinesOwned").bits!=1 || vm.invoke("GetGoldOwned").bits!=73 || base->resources!=73)throw std::runtime_error("Restored covered mine balance was not detected");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS covered_mine race="<<race<<" extracted="<<extracted<<"\n";
}
